{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Danazol, the highest-transfer steroid analogue, showed only 19% absolute oral bioavailability in fasted humans, just below the 20% threshold; however, its fed-state bioavailability is much higher (44-67%), indicating a solubility-limited rather than permeability-limited absorption concern.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C64"],
      "claim": "Dutasteride, a highly lipophilic steroid-like molecule with bulky aromatic substituents, has approximately 60% absolute oral bioavailability (range 40-94%) in humans, demonstrating that lipophilic steroids can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Esaxerenone, which contains the same methylsulfonylphenyl motif as the query, has 89% absolute oral bioavailability in fasting humans, directly supporting high F for this structural feature.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Odanacatib, bearing methylsulfonyl and trifluoromethyl groups, had 30% absolute oral bioavailability at a 50 mg fasted dose and 70% at 10 mg, remaining above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Cilomilast is almost completely bioavailable (96%) in humans, supporting high F for a small lipophilic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Digitoxin, a steroid glycoside, has >90% absolute oral bioavailability, supporting high F for steroid scaffolds.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable human absolute-bioavailability evidence supports high F (>=20%). Multiple steroid and methylsulfonylphenyl-containing analogues (dutasteride, esaxerenone, odanacatib, digitoxin, cilomilast) show F values of 30-100%. The only sub-threshold evidence, danazol in the fasted state, is condition-dependent and rises above 20% with food or commercial capsules; the query's methylsulfonylphenyl group likely mitigates the solubility limitation. Therefore predict high with moderate confidence.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "The endpoint does not specify fed versus fasted conditions; danazol shows a strong food effect and the query's fasted-state solubility-limited absorption is uncertain.",
    "Dose-dependent bioavailability observed for odanacatib suggests the query's F may depend on dose and formulation.",
    "First-pass metabolism of the pentafluoroethyl carbinol and methylsulfonylphenyl steroid scaffold is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

